#!/bin/sh
# Runs INSIDE the build container (called by user/cc/build.sh).
#   /linux  = the uClinux tree (only read from)
#   /build  = user/cc
# Builds libc.a and libm.a without -msep-data into /build/build/lib.
# The sources are copied to a shadow tree first, so the normal
# (-msep-data) objects in uClinux/lib are not touched.
#
# Generated by LLM

set -e

U=/tmp/uclinux-abs
rm -rf "$U"
mkdir -p "$U/lib"
for f in .config config config.arch vendors linux-2.0.x; do
    ln -s "/linux/$f" "$U/$f"
done
cp -a /linux/lib/libc /linux/lib/libm "$U/lib/"
find "$U/lib" \( -name '*.o' -o -name '*.a' -o -name '.ranlib' \) -exec rm -f {} +

make -s -f /build/libc-abs.mk ROOTDIR="$U"

mkdir -p /build/build/lib
cp "$U/lib/libc/libc.a" "$U/lib/libm/libm.a" /build/build/lib/
echo "libc.a / libm.a (no -msep-data) -> user/cc/build/lib"
